const { useState } = React;

const RadioOption = ({ id, name, value, label, checked, onChange }) => {
  return (
    <label htmlFor={id} className="radio-option">
      <input
        type="radio"
        id={id}
        name={name}
        value={value}
        checked={checked}
        onChange={() => onChange(value)}
        required
      />
      <span className="radio-label">{label}</span>
    </label>
  );
};

const RadioGroup = ({ legend, options, name, value, onChange }) => {
  return (
    <div className="form-field">
      <fieldset>
        <legend>{legend}</legend>
        <div className="radio-group">
          {options.map((option) => (
            <RadioOption
              key={option.id}
              id={option.id}
              name={name}
              value={option.value}
              label={option.label}
              checked={value === option.value}
              onChange={onChange}
            />
          ))}
        </div>
      </fieldset>
    </div>
  );
};

const NotificationForm = () => {
  const [preference, setPreference] = useState('');

  const options = [
    { id: 'pref-email', value: 'email', label: 'Email' },
    { id: 'pref-sms', value: 'sms', label: 'SMS' },
    { id: 'pref-push', value: 'push', label: 'Push Notifications' }
  ];

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) {
      alert('Please select a preference.');
      return;
    }
    console.log('Selected preference:', preference);
    alert(`Success! Your preference "${preference}" has been saved.`);
  };

  return (
    <form onSubmit={handleSubmit} noValidate={false}>
      <RadioGroup
        legend="How do you prefer to receive notifications?"
        name="notification-preference"
        options={options}
        value={preference}
        onChange={setPreference}
      />
      <button type="submit">Save Preferences</button>
    </form>
  );
};

const App = () => {
  return (
    <main>
      <h1>Settings</h1>
      <NotificationForm />
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
