    { id: 'pref-sms', value: 'sms', label: 'SMS' },
    { id: 'pref-push', value: 'push', label: 'Push Notifications' }
  ];

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) {
      alert('Please select a preference.');
      return;
