               name={name}
               value={option.value}
               label={option.label}
               checked={value === option.value}
               onChange={onChange}
             />
           ))}
         </div>
       </fieldset>
     </div>
   );
 };

 const NotificationForm = () => {
   const [preference, setPreference] = useState('');

   const options = [
